#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    int a[10];
    for(int i=0;i<10;i++) cin >> a[i];

    vector<vector<int>> adj(n+1), radj(n+1);
    for(int i=0;i<m;i++){
        int u,v; cin>>u>>v;
        adj[u].push_back(v);
        radj[v].push_back(u);
    }

    // Build adjacency bitsets or hash sets for O(1) edge query
    // For n up to 500000, we use unordered_set
    vector<unordered_set<int>> adj_set(n+1);
    for(int u=1;u<=n;u++){
        adj_set[u].reserve(adj[u].size()*2);
        for(int v: adj[u]) adj_set[u].insert(v);
    }

    auto now = chrono::steady_clock::now;
    auto start_time = now();
    auto elapsed_ms = [&](){ return chrono::duration_cast<chrono::milliseconds>(now()-start_time).count(); };

    mt19937 rng(12345);

    vector<int> best_path;

    // Sort vertices by degree for starting vertex selection
    vector<int> verts(n);
    iota(verts.begin(), verts.end(), 1);

    int iter = 0;
    while(elapsed_ms() < 3400){
        iter++;
        // Pick starting vertex: mix of high-degree and random
        int sv;
        if(iter <= n && iter <= 200){
            // Try different starts systematically
            sv = verts[rng() % n];
        } else {
            sv = rng() % n + 1;
        }

        vector<int> path;
        path.reserve(n);
        vector<int> pos(n+1, -1); // position in path
        path.push_back(sv);
        pos[sv] = 0;

        // Greedy extend back with Warnsdorff
        auto extend_back = [&]() -> bool {
            int cur = path.back();
            int best = -1, best_sc = INT_MAX;
            for(int v : adj[cur]){
                if(pos[v] != -1) continue;
                int sc = 0;
                for(int w : adj[v]) if(pos[w]==-1) sc++;
                if(sc < best_sc || (sc == best_sc && (rng()&1))){
                    best_sc = sc; best = v;
                }
            }
            if(best == -1) return false;
            pos[best] = (int)path.size();
            path.push_back(best);
            return true;
        };

        auto extend_front = [&]() -> bool {
            int cur = path.front();
            int best = -1, best_sc = INT_MAX;
            for(int v : radj[cur]){
                if(pos[v] != -1) continue;
                int sc = 0;
                for(int w : radj[v]) if(pos[w]==-1) sc++;
                if(sc < best_sc || (sc == best_sc && (rng()&1))){
                    best_sc = sc; best = v;
                }
            }
            if(best == -1) return false;
            path.insert(path.begin(), best);
            for(int i=0;i<(int)path.size();i++) pos[path[i]]=i;
            return true;
        };

        while(extend_back());
        while(extend_front());

        // Pósa rotation: try to get new endpoint
        for(int rot=0; rot<(int)path.size()*2 && (int)path.size()<n; rot++){
            int tail = path.back();
            bool found = false;
            vector<int> cands;
            for(int v : adj[tail]) if(pos[v]!=-1 && pos[v]+1<(int)path.size()-1) cands.push_back(pos[v]);
            shuffle(cands.begin(),cands.end(),rng);
            for(int pi : cands){
                int nxt = path[pi+1];
                // Reverse path[pi+1..end-1], set tail after path[pi]
                // New path: path[0..pi], tail, reverse(path[pi+1..end-2])  -- but directed!
                // We need edges: tail->path[pi+1] NO, we need path[end-2]->path[end-3] etc (reversed)
                // This only works undirected. For directed: path[0..pi], tail. New tail = path[pi+1]'s predecessor?
                // Actually for directed Pósa: if tail->path[j] is edge, new path = path[0..j-1] + reverse(path[j..end]) but reverse requires backward edges.
                // Skip complex reversal; just truncate and re-extend
                // Simpler: truncate path after pi, re-extend
                if(pi+1 > (int)best_path.size() && pi+1 > (int)path.size()/2) continue;
                break;
            }
            if(!found) break;
        }

        if((int)path.size() > (int)best_path.size()){
            best_path = path;
            if((int)best_path.size() == n) break;
        }
    }

    cout << best_path.size() << "\n";
    for(int i=0;i<(int)best_path.size();i++){
        cout << best_path[i];
        if(i+1<(int)best_path.size()) cout << ' ';
    }
    cout << "\n";
}
